            t_DiffuseLighting += v_DiffuseLighting0.rgb * t_Influence.x;
            t_DiffuseLighting += v_DiffuseLighting1.rgb * t_Influence.y;
            t_DiffuseLighting += v_DiffuseLighting2.rgb * t_Influence.z;
